
(()=>{
  const STORAGE_KEY='lingua_daily_workbench_v1';
  const DAY=86400000;
  const INTERVALS=[1,2,4,7,15,30];
  const byId=id=>document.getElementById(id);
  const localDay=(date=new Date())=>{const d=new Date(date);d.setHours(0,0,0,0);return d.getTime()};
  const dateLabel=(stamp)=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(stamp||Date.now());
  const todayKey=()=>new Date().toLocaleDateString('en-CA');
  const addDays=(stamp,days)=>{const d=new Date(stamp);d.setDate(d.getDate()+days);return d.getTime()};
  const sample=()=>{const now=Date.now(),today=localDay();return[
    {word:'curious',pron:'/ˈkjʊriəs/',meaning:'好奇的；求知欲强的',example:'Children are naturally curious about the world.',usage:'be curious about sth. 对……感到好奇',tags:['形容词','日常表达'],stage:1,learnedAt:today-4*DAY,nextReviewAt:today,lastReviewedAt:null,reviewCount:1,createdAt:today-4*DAY,explanation:''},
    {word:'overlook',pron:'/ˌoʊvərˈlʊk/',meaning:'忽略；未注意到',example:'It is easy to overlook small details.',usage:'overlook a detail / mistake',tags:['动词','阅读'],stage:1,learnedAt:today-2*DAY,nextReviewAt:today,lastReviewedAt:null,reviewCount:1,createdAt:today-2*DAY,explanation:''},
    {word:'compelling',pron:'/kəmˈpelɪŋ/',meaning:'引人入胜的；令人信服的',example:'She made a compelling argument.',usage:'a compelling reason / story',tags:['形容词','写作'],stage:2,learnedAt:today-6*DAY,nextReviewAt:today,lastReviewedAt:null,reviewCount:2,createdAt:today-6*DAY,explanation:''},
    {word:'perspective',pron:'/pərˈspektɪv/',meaning:'观点；视角；看法',example:'Try to see the issue from her perspective.',usage:'from a different perspective',tags:['名词','沟通'],stage:0,learnedAt:today-1*DAY,nextReviewAt:today,lastReviewedAt:null,reviewCount:0,createdAt:today-1*DAY,explanation:''},
    {word:'articulate',pron:'/ɑːrˈtɪkjələt/',meaning:'清楚表达；善于表达的',example:'He struggled to articulate his thoughts.',usage:'articulate an idea / clearly articulate',tags:['动词','表达'],stage:0,learnedAt:null,nextReviewAt:today, lastReviewedAt:null,reviewCount:0,createdAt:today,explanation:''},
    {word:'subtle',pron:'/ˈsʌtəl/',meaning:'微妙的；不易察觉的',example:'There is a subtle difference in tone.',usage:'a subtle difference / change',tags:['形容词','阅读'],stage:0,learnedAt:null,nextReviewAt:today,lastReviewedAt:null,reviewCount:0,createdAt:today,explanation:''},
    {word:'resilient',pron:'/rɪˈzɪliənt/',meaning:'有韧性的；能迅速恢复的',example:'Young plants are surprisingly resilient.',usage:'a resilient person / community',tags:['形容词','进阶'],stage:0,learnedAt:null,nextReviewAt:today,lastReviewedAt:null,reviewCount:0,createdAt:today,explanation:''},
    {word:'reinforce',pron:'/ˌriːɪnˈfɔːrs/',meaning:'加强；巩固；强化',example:'Regular practice reinforces what you learn.',usage:'reinforce a habit / memory / idea',tags:['动词','学习'],stage:0,learnedAt:null,nextReviewAt:today,lastReviewedAt:null,reviewCount:0,createdAt:today,explanation:''}
  ].map(w=>({...w,id:crypto.randomUUID(),stage:0,learnedAt:null,lastReviewedAt:null,reviewCount:0,createdAt:now,nextReviewAt:today}))};
  const defaultState=()=>({words:sample(),streak:0,lastStudyDate:null,studyDays:[],weeklyMinutes:0,weeklyData:[0,0,0,0,0,0,0],quizCompletedOn:null,reminderEnabled:false,reminderTime:'20:00',remindedOn:null,language:'英语 · English'});
  let workspace;
  function createProfile(language) {
    const profile = defaultState();
    profile.language = language;
    profile.weeklyData = [0,0,0,0,0,0,0];
    const starter = LinguaCore.starter(language);
    if (language !== LinguaCore.languages[0]) {
      profile.words = starter.words.map(([word,pron,meaning,example]) => ({
        id:crypto.randomUUID(),word,pron,meaning,example,usage:'',tags:[],
        stage:0,learnedAt:null,nextReviewAt:Date.now(),lastReviewedAt:null,reviewCount:0,createdAt:Date.now()
      }));
    }
    profile.materials = starter.materials;
    profile.practice = {};
    return profile;
  }
  function load() {
    try { workspace = JSON.parse(localStorage.getItem('lingua_workbench_v2')); } catch {}
    if (!workspace?.profiles) {
      let legacy;
      try { legacy = JSON.parse(localStorage.getItem(STORAGE_KEY)); } catch {}
      const english = createProfile(LinguaCore.languages[0]);
      if (Array.isArray(legacy?.words)) Object.assign(english,legacy,{language:LinguaCore.languages[0]});
      workspace = {active:legacy?.language || LinguaCore.languages[0],profiles:{[LinguaCore.languages[0]]:english}};
    }
    if (!LinguaCore.languages.includes(workspace.active)) workspace.active=LinguaCore.languages[0];
    workspace.profiles[workspace.active] ||= createProfile(workspace.active);
    return workspace.profiles[workspace.active];
  }
  let state=load(),currentView='home',session=null,quiz=null,toastTimer,feynmanTarget=null;
  const save = () => {
    workspace.profiles[state.language] = state;
    localStorage.setItem('lingua_workbench_v2',JSON.stringify(workspace));
  };
  const isDue=w=>w.learnedAt!==null&&w.learnedAt!==undefined&&Number(w.nextReviewAt||0)<=Date.now();
  const dueWords=()=>state.words.filter(isDue);
  const newWords=()=>state.words.filter(w=>w.learnedAt===null||w.learnedAt===undefined);
  const todayReviews=()=>state.words.filter(w=>w.lastReviewedAt&&new Date(w.lastReviewedAt).toLocaleDateString('en-CA')===todayKey()).length;
  const completedTasks=()=>({review:todayReviews()>0||state.words.length>0&&dueWords().length===0&&state.words.some(w=>w.lastReviewedAt&&new Date(w.lastReviewedAt).toLocaleDateString('en-CA')===todayKey()),new:newWords().length===0||state.words.some(w=>w.learnedAt&&new Date(w.learnedAt).toLocaleDateString('en-CA')===todayKey()),quiz:state.quizCompletedOn===todayKey()});
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmtShort=stamp=>new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric'}).format(stamp);
  const showToast=msg=>{const el=byId('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)};
  const setView=view=>{currentView=view;document.querySelectorAll('.page-view').forEach(el=>el.classList.toggle('active',el.id==='view-'+view));document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const names={home:'今日工作台',vocab:'我的词库',review:'间隔复习',quiz:'快速测验',progress:'学习报告'};byId('crumbTitle').textContent=names[view]||'今日工作台';window.scrollTo({top:0,behavior:'smooth'});if(view==='review')renderReviewIdle();if(view==='quiz'&&!quiz)renderQuizIntro();if(view==='vocab')renderVocab();};
  const setTaskCompleted=(key)=>{const completed=completedTasks();completed[key]=true; if(key==='quiz')state.quizCompletedOn=todayKey(); if(key==='new'&&newWords().length===0) state.newCompletedOn=todayKey();if(key==='review'&&todayReviews()>0)state.reviewCompletedOn=todayKey();save();render()};
  const taskState=()=>{const today=todayKey();return{review:state.reviewCompletedOn===today||todayReviews()>0,new:state.newCompletedOn===today||state.words.some(w=>w.learnedAt&&new Date(w.learnedAt).toLocaleDateString('en-CA')===today),quiz:state.quizCompletedOn===today}};
  function renderTasks(){const done=taskState();const due=dueWords().length, fresh=newWords().length;const list=[{key:'review',icon:'⟳',color:'',name:'间隔复习',meta:`${due} 个到期词 · 先回忆，再翻卡片核对`,time:'约 5 分钟',view:'review',empty:'今天没有到期词了，节奏刚刚好。'},{key:'new',icon:'✦',color:'blue',name:'学习新词',meta:`${fresh} 个新词 · 选几个表达加入今天的记忆`,time:'约 7 分钟',view:'review',empty:'新词已学完，可以添加自己的词条。'},{key:'quiz',icon:'✓',color:'orange',name:'快速测验',meta:'用主动回忆检测今天的学习效果',time:'约 3 分钟',view:'quiz',empty:'测验已完成，做得不错。'}];byId('todayTasks').innerHTML=list.map(t=>{const isDone=done[t.key];return `<article class="task ${isDone?'done':''}"><button class="task-check" data-task="${t.key}" aria-label="${isDone?'已完成':'标记完成'}">${isDone?'✓':''}</button><span class="task-icon ${t.color}">${t.icon}</span><div class="task-details"><div class="task-name">${t.name}</div><div class="task-meta">${esc(isDone?t.empty:t.meta)}</div></div><span class="task-time">${isDone?'已完成':t.time}</span><button class="text-btn" data-task-open="${t.view}" aria-label="开始${t.name}">${isDone?'查看':'开始'}</button></article>`}).join('');byId('todayTasks').querySelectorAll('[data-task-open]').forEach(b=>b.onclick=()=>{const key=b.dataset.taskOpen;if(key==='review')beginSession(b.closest('.task').querySelector('[data-task]').dataset.task==='new'?'new':'due');else if(key==='quiz'){setView('quiz');startQuiz()}else beginSession('new')});byId('todayTasks').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const k=b.dataset.task;if(k==='review'&&!dueWords().length){showToast('今天的到期复习已经完成');return}if(k==='new'&&!newWords().length){byId('wordDialog').showModal();return}if(k==='quiz'){setView('quiz');startQuiz()}else beginSession(k==='new'?'new':'due')});}
  function renderChart(){const today=new Date().getDay(),labels=['日','一','二','三','四','五','六'],values=Array.isArray(state.weeklyData)?state.weeklyData.slice(-7):[0,0,0,0,0,0,0];const start=(today+1)%7;const ordered=labels.slice(start).concat(labels.slice(0,start));const vals=values.slice(start).concat(values.slice(0,start));const max=Math.max(20,...vals);byId('weekChart').innerHTML=ordered.map((d,i)=>`<div class="chart-col"><div class="chart-bar ${i===6?'today':''}" style="height:${Math.max(8,vals[i]/max*58)}px" data-value="${vals[i]?vals[i]+'m':''}"></div><div class="chart-day">${i===6?'今':d}</div></div>`).join('')}
  function renderRecent(){const words=[...state.words].sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,4);byId('recentWords').innerHTML=words.length?words.map(w=>`<div class="word-row"><div><div class="word-main">${esc(w.word)}</div><div class="word-pron">${esc(w.pron||'—')}</div></div><div class="word-meaning">${esc(w.meaning)}</div><div class="word-example">${esc(w.example||w.usage||'尚未添加例句')}</div><span class="word-status">${w.learnedAt?'学习中':'新词'}</span></div>`).join(''):'<div class="empty-state"><strong>词库还是空的</strong><p>添加第一个词条，建立自己的学习素材。</p></div>'}
  function render(){const due=dueWords().length,fresh=newWords().length,done=taskState(),count=Object.values(done).filter(Boolean).length,pct=Math.round(count/3*100);byId('todayDate').textContent=dateLabel();byId('todayEyebrow').textContent=new Intl.DateTimeFormat('en-US',{weekday:'long'}).format(new Date()).toUpperCase()+' · DAILY FOCUS';byId('metricDue').innerHTML=`${due}<small>个词</small>`;byId('metricNew').innerHTML=`${fresh}<small>个词</small>`;byId('metricStreak').innerHTML=`${state.streak||0}<small>天</small>`;byId('metricWeek').innerHTML=`${state.weeklyMinutes||0}<small>分钟</small>`;byId('navDue').textContent=due;byId('navDue').hidden=!due;byId('ringPercent').textContent=pct+'%';byId('progressRing').style.setProperty('--progress',pct+'%');byId('heroProgressText').textContent=`完成 ${count} / 3 个环节`;renderTasks();renderChart();renderRecent();renderVocab();renderReports();byId('notifyDot').hidden=!state.reminderEnabled;byId('languageSelect').value=state.language||'英语 · English'}
  function renderVocab(){if(!byId('vocabList'))return;const search=(byId('searchWords')?.value||'').trim().toLowerCase(),filter=byId('filterWords')?.value||'all',sort=byId('sortWords')?.value||'recent';let words=state.words.filter(w=>{const q=[w.word,w.pron,w.meaning,w.example,w.usage,...(w.tags||[])].join(' ').toLowerCase();return(!search||q.includes(search))&&(filter==='all'||(filter==='due'?isDue(w):!w.learnedAt))});if(sort==='alpha')words.sort((a,b)=>a.word.localeCompare(b.word));else if(sort==='due')words.sort((a,b)=>(a.nextReviewAt||0)-(b.nextReviewAt||0));else words.sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));byId('vocabList').innerHTML=words.length?words.map(w=>`<div class="word-row"><div><div class="word-main">${esc(w.word)}</div><div class="word-pron">${esc(w.pron||'尚未记录读音')}</div></div><div class="word-meaning">${esc(w.meaning)}</div><div class="word-example" title="${esc(w.example||w.usage||'')}">${esc(w.example||w.usage||'暂无例句')}</div><span class="word-status">${w.learnedAt?`第 ${Math.min((w.stage||0)+1,INTERVALS.length)} 阶段`:'新词'}</span><div class="row-actions"><button class="small-icon" title="播放读音" aria-label="播放${esc(w.word)}" data-speak="${esc(w.word)}">◖</button><button class="small-icon" title="编辑" aria-label="编辑${esc(w.word)}" data-edit="${w.id}">✎</button><button class="small-icon" title="删除" aria-label="删除${esc(w.word)}" data-delete="${w.id}">×</button></div></div>`).join(''):'<div class="empty-state"><strong>没有找到词条</strong><p>调整筛选条件，或添加新的表达。</p></div>';byId('vocabList').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editWord(b.dataset.edit));byId('vocabList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteWord(b.dataset.delete));byId('vocabList').querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));}
  function renderReports(){byId('reportWords').textContent=state.words.length;byId('reportMastered').textContent=state.words.filter(w=>(w.stage||0)>=3).length;byId('reportReviews').textContent=state.words.reduce((n,w)=>n+(w.reviewCount||0),0);const labels=['当天学习','1 天后','2 天后','4 天后','7 天后','15 天后','30 天后'];const counts=[0,0,0,0,0,0,0];state.words.forEach(w=>{const i=Math.min((w.stage||0)+1,6);counts[i]++});const max=Math.max(1,...counts);byId('stageBars').innerHTML=labels.map((label,i)=>`<div class="report-bar-row"><span>${label}</span><div class="report-bar-track"><div class="report-bar-fill" style="width:${counts[i]/max*100}%"></div></div><span>${counts[i]} 个</span></div>`).join('')}
  function addMinutes(minutes=5){state.weeklyMinutes=(state.weeklyMinutes||0)+minutes;const d=new Date().getDay(),arr=state.weeklyData||[0,0,0,0,0,0,0];arr[d]=Math.min(60,(arr[d]||0)+minutes);state.weeklyData=arr;const key=todayKey();if(state.lastStudyDate!==key){const yesterday=new Date(Date.now()-DAY).toLocaleDateString('en-CA');state.streak=state.lastStudyDate===yesterday?(state.streak||0)+1:1;state.lastStudyDate=key;state.studyDays=[...(state.studyDays||[]).filter(x=>x!==key),key]}}
  function beginSession(type){const pool=type==='new'?newWords():dueWords();if(!pool.length){if(type==='due'){showToast('今天没有到期词，试试学习新词');if(newWords().length)beginSession('new');else setView('review')}else{showToast('词库里暂时没有新词');setView('vocab')}return}session={type,queue:pool.map(w=>w.id),index:0,show:false};setView('review');renderSession()}
  function renderReviewIdle(){if(session)return;const due=dueWords().length,fresh=newWords().length;byId('flashLabel').textContent='艾宾浩斯 · 主动回忆';byId('flashWord').textContent=due?`${due} 个词等你复习`:'复习完成';byId('flashPron').textContent=due?'先说出释义和用法，再翻开卡片。':fresh?`还有 ${fresh} 个新词可以开始学习。`:'今天的复习已经清空。';byId('flashBack').hidden=true;byId('flashHint').textContent='点击「开始复习」或「学习新词」开始一轮练习';byId('againButton').disabled=true;byId('knownButton').disabled=true;byId('reviewProgressText').textContent='0 / 0';byId('reviewProgress').style.width='0%';byId('reviewDueLabel').textContent=`今日有 ${due} 个词到期`}
  function renderSession(){if(!session)return;const word=state.words.find(w=>w.id===session.queue[session.index]);if(!word){finishSession();return}byId('flashLabel').textContent=`${session.type==='new'?'新词 · 先建立初次记忆':'复习 · 回想含义与用法'}　${session.index+1} / ${session.queue.length}`;byId('flashWord').textContent=word.word;byId('flashPron').textContent=word.pron||'读音待补充';byId('flashMeaning').textContent=word.meaning;byId('flashExample').textContent=word.example?`“${word.example}”`:'';byId('flashUsage').textContent=word.usage||'';byId('flashBack').hidden=!session.show;byId('flashHint').textContent=session.show?'核对后，选择「记住了」或「还不熟」':'先试着自己说出释义，再点击卡片查看答案';byId('againButton').disabled=!session.show;byId('knownButton').disabled=!session.show;byId('reviewProgressText').textContent=`${session.index} / ${session.queue.length}`;byId('reviewProgress').style.width=`${Math.round(session.index/session.queue.length*100)}%`;byId('reviewDueLabel').textContent=`本轮共 ${session.queue.length} 个词`}
  function revealCard(){if(!session)return;session.show=true;renderSession()}
  function scoreReview(known){const word=state.words.find(w=>w.id===session.queue[session.index]);if(!word)return;if(known){if(!word.learnedAt){word.learnedAt=Date.now();word.stage=0;word.nextReviewAt=addDays(Date.now(),INTERVALS[0])}else{word.stage=Math.min((word.stage||0)+1,INTERVALS.length-1);word.nextReviewAt=addDays(Date.now(),INTERVALS[word.stage])}}else{if(word.learnedAt){word.stage=0;word.nextReviewAt=addDays(Date.now(),1)}else{word.nextReviewAt=Date.now()}}word.lastReviewedAt=Date.now();word.reviewCount=(word.reviewCount||0)+1;session.index++;session.show=false;addMinutes(1);save();if(session.index>=session.queue.length)finishSession();else renderSession();render()}
  function finishSession(){const kind=session?.type;feynmanTarget=session?.queue[session.queue.length-1]||null;session=null;save();render();byId('flashLabel').textContent='本轮完成';byId('flashWord').textContent='做得很好';byId('flashPron').textContent=kind==='new'?'新词已进入复习计划。':'这轮复习已完成，下一次会按记忆间隔出现。';byId('flashBack').hidden=true;byId('flashHint').textContent='用一句简单的话复述刚才最难的词，巩固记忆。';byId('againButton').disabled=true;byId('knownButton').disabled=true;byId('reviewProgressText').textContent=`${kind==='new'?'新词':'复习'}已完成`;byId('reviewProgress').style.width='100%';byId('reviewDueLabel').textContent=`剩余到期词 ${dueWords().length} 个`;if(kind==='new')state.newCompletedOn=todayKey();if(kind==='due'&&dueWords().length===0)state.reviewCompletedOn=todayKey();save();render();showToast(kind==='new'?'学习完成，新词已安排后续复习':'复习完成，记忆间隔已更新');byId('feynmanWordLabel').textContent='回想一下刚才的词，用自己的话解释或造句';byId('feynmanText').value='';byId('feynmanDialog').showModal()}
  function renderQuizIntro(){const available=state.words.filter(w=>w.meaning);byId('quizShell').innerHTML=`<div class="quiz-card" style="text-align:center;padding:42px 28px"><div class="eyebrow">3–5 MINUTES · ACTIVE RECALL</div><h2 style="margin:6px 0 8px;font-size:23px">准备好检验记忆了吗？</h2><p style="color:var(--muted);font-size:14px;margin:0 auto 21px;max-width:460px">从词库中抽取最多 5 个词，选择正确释义。答错的词会重新进入较短复习间隔。</p><div style="color:#7e8b83;font-size:12px;margin-bottom:19px">当前可测验词条：${available.length} 个</div><button class="button primary" id="quizStartInner">开始测验</button></div>`;byId('quizStartInner').onclick=startQuiz}
  function startQuiz(){const pool=state.words.filter(w=>w.meaning);if(!pool.length){renderQuizIntro();showToast('先添加一些词条，再开始测验');return}const picked=[...pool].sort(()=>Math.random()-.5).slice(0,Math.min(5,pool.length));quiz={items:picked.map(w=>w.id),index:0,score:0,answered:false,correct:null};renderQuizQuestion()}
  function renderQuizQuestion(){if(!quiz)return;quiz.answered=false;quiz.correct=null;const w=state.words.find(x=>x.id===quiz.items[quiz.index]);if(!w){finishQuiz();return}const others=state.words.filter(x=>x.id!==w.id);const opts=[w,...[...others].sort(()=>Math.random()-.5).slice(0,3)].sort(()=>Math.random()-.5);quiz.currentOptions=opts.map(x=>x.id);byId('quizShell').innerHTML=`<div class="quiz-card"><div class="quiz-top"><span>第 ${quiz.index+1} 题 / ${quiz.items.length}</span><span>答对 ${quiz.score} 题</span></div><div class="quiz-word">${esc(w.word)}</div><div class="quiz-pron">${esc(w.pron||'')}</div><div class="quiz-prompt">请选择最贴近的释义</div><div class="choices">${opts.map(o=>`<button class="choice" data-choice="${o.id}" ${quiz.answered?'disabled':''}>${esc(o.meaning)}</button>`).join('')}</div><div class="quiz-feedback" id="quizFeedback">${quiz.answered?(quiz.correct?'回答正确。':'再看一遍例句，留意这个词的使用语境。'):''}</div><div class="quiz-bottom"><button class="text-btn" id="quizExit">退出测验</button><button class="button primary" id="quizNext" ${quiz.answered?'':'disabled'}>${quiz.index===quiz.items.length-1?'查看结果':'下一题'}</button></div></div>`;byId('quizShell').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answerQuiz(b.dataset.choice,w));byId('quizNext').onclick=()=>{if(!quiz.answered)return;quiz.index++;if(quiz.index>=quiz.items.length)finishQuiz();else renderQuizQuestion()};byId('quizExit').onclick=()=>{quiz=null;renderQuizIntro()}}
  function answerQuiz(id,w){if(!quiz||quiz.answered)return;quiz.answered=true;quiz.correct=id===w.id;if(quiz.correct)quiz.score++;else{w.stage=0;w.nextReviewAt=Date.now();save()}byId('quizShell').querySelectorAll('[data-choice]').forEach(b=>{if(b.dataset.choice===w.id)b.classList.add('correct');else if(b.dataset.choice===id)b.classList.add('wrong')});byId('quizFeedback').textContent=quiz.correct?'回答正确，记忆稳固。':`正确释义：${w.meaning}。${w.example||''}`;byId('quizNext').disabled=false}
  function finishQuiz(){const score=quiz.score,total=quiz.items.length;quiz=null;state.quizCompletedOn=todayKey();addMinutes(3);save();render();byId('quizShell').innerHTML=`<div class="quiz-card" style="text-align:center;padding:42px 28px"><div class="eyebrow">SESSION COMPLETE</div><h2 style="font-size:24px;margin:7px 0">本轮得分</h2><div style="font-size:50px;font-weight:760;color:var(--green);letter-spacing:-.05em">${score}<span style="font-size:20px;color:#99a49e"> / ${total}</span></div><p style="color:var(--muted);font-size:14px">${score===total?'全部答对，今天的记忆状态很稳。':'错题已安排较短复习间隔，过一会儿再主动回忆。'}</p><button class="button primary" id="quizAgain">再测一组</button> <button class="button" id="quizHome">回到今日工作台</button></div>`;byId('quizAgain').onclick=startQuiz;byId('quizHome').onclick=()=>setView('home');showToast('测验完成，结果已记入今日计划')}
  function openAdd(){byId('wordDialogTitle').textContent='添加词条';byId('wordForm').reset();byId('editId').value='';byId('wordDialog').showModal()}
  function editWord(id){const w=state.words.find(x=>x.id===id);if(!w)return;byId('wordDialogTitle').textContent='编辑词条';byId('editId').value=id;byId('wordInput').value=w.word;byId('pronInput').value=w.pron||'';byId('meaningInput').value=w.meaning;byId('exampleInput').value=w.example||'';byId('usageInput').value=w.usage||'';byId('tagInput').value=(w.tags||[]).join(', ');byId('wordDialog').showModal()}
  function deleteWord(id){const word=state.words.find(w=>w.id===id);if(!word)return;if(!confirm(`删除「${word.word}」？`))return;state.words=state.words.filter(w=>w.id!==id);save();render();showToast('词条已删除')}
  function saveWord(e){e.preventDefault();const id=byId('editId').value,existing=state.words.find(w=>w.id===id);const entry={id:id||crypto.randomUUID(),word:byId('wordInput').value.trim(),pron:byId('pronInput').value.trim(),meaning:byId('meaningInput').value.trim(),example:byId('exampleInput').value.trim(),usage:byId('usageInput').value.trim(),tags:byId('tagInput').value.split(',').map(x=>x.trim()).filter(Boolean),stage:existing?.stage||0,learnedAt:existing?.learnedAt??null,nextReviewAt:existing?.nextReviewAt??localDay(),lastReviewedAt:existing?.lastReviewedAt||null,reviewCount:existing?.reviewCount||0,createdAt:existing?.createdAt||Date.now(),explanation:existing?.explanation||''};if(!entry.word||!entry.meaning)return;if(existing)state.words=state.words.map(w=>w.id===id?entry:w);else state.words.unshift(entry);save();byId('wordDialog').close();render();showToast(existing?'词条已更新':'已添加到词库')}
  function importWords(e){e.preventDefault();const lines=byId('bulkInput').value.trim().split(/\r?\n/).filter(Boolean);let count=0;for(const line of lines){const parts=line.split('\t');if(!parts[0]?.trim()||!parts[2]?.trim())continue;state.words.unshift({id:crypto.randomUUID(),word:parts[0].trim(),pron:(parts[1]||'').trim(),meaning:parts[2].trim(),example:(parts[3]||'').trim(),usage:(parts[4]||'').trim(),tags:(parts[5]||'').split(/[,，]/).map(x=>x.trim()).filter(Boolean),stage:0,learnedAt:null,nextReviewAt:localDay(),lastReviewedAt:null,reviewCount:0,createdAt:Date.now(),explanation:''});count++}save();byId('importDialog').close();byId('bulkInput').value='';render();showToast(`已导入 ${count} 个词条`)}
  function ankiExport(){if(!state.words.length){showToast('词库为空，暂时没有可导出的词条');return}const fields=['Word','Pronunciation','Meaning','Example','Usage','Tags'];const clean=s=>String(s||'').replace(/[\t\r\n]+/g,' ').trim();const rows=state.words.map(w=>[w.word,w.pron,w.meaning,w.example,w.usage,(w.tags||[]).join(' ')]);const blob=new Blob(['#separator:Tab\n#html:false\n#columns:'+fields.join('\t')+'\n'+rows.map(row=>row.map(clean).join('\t')).join('\n')],{type:'text/tab-separated-values;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lingua-anki-vocabulary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Anki 词条文件已下载，可在 Anki 中导入')}
  function speak(text){if(!('speechSynthesis'in window)){showToast('此浏览器暂不支持语音朗读');return}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);const lang=(state.language||'').split(' · ')[0];u.lang=lang.includes('日语')?'ja-JP':lang.includes('韩语')?'ko-KR':lang.includes('法语')?'fr-FR':lang.includes('西班牙语')?'es-ES':'en-US';u.rate=.88;window.speechSynthesis.speak(u)}
  function reminderOpen(){byId('reminderToggle').checked=!!state.reminderEnabled;byId('reminderTime').value=state.reminderTime||'20:00';byId('reminderDialog').showModal()}
  async function saveReminder(e){e.preventDefault();const enabled=byId('reminderToggle').checked;state.reminderTime=byId('reminderTime').value||'20:00';if(enabled){if(!('Notification'in window)){showToast('当前浏览器不支持桌面通知');state.reminderEnabled=false}else{let perm=Notification.permission;if(perm==='default')perm=await Notification.requestPermission();state.reminderEnabled=perm==='granted';if(!state.reminderEnabled)showToast('通知权限未开启，提醒设置未生效')}}else state.reminderEnabled=false;save();byId('reminderDialog').close();render();if(state.reminderEnabled)showToast(`每日提醒已设为 ${state.reminderTime}`)}
  function checkReminder(){if(!state.reminderEnabled||!('Notification'in window)||Notification.permission!=='granted')return;const now=new Date(),time=now.toTimeString().slice(0,5);if(time>=state.reminderTime&&state.remindedOn!==todayKey()){const due=dueWords().length,fresh=newWords().length;new Notification('今天的语言学习时间到了',{body:`${due} 个待复习 · ${fresh} 个新词 · 再花几分钟完成小测验`,icon:'icon.svg',tag:'lingua-daily-plan'});state.remindedOn=todayKey();save()}}
  byId('wordForm').addEventListener('submit',saveWord);byId('importForm').addEventListener('submit',importWords);byId('reminderForm').addEventListener('submit',saveReminder);byId('feynmanForm').addEventListener('submit',e=>{e.preventDefault();const text=byId('feynmanText').value.trim();if(feynmanTarget&&text){const w=state.words.find(x=>x.id===feynmanTarget);if(w)w.explanation=text}feynmanTarget=null;byId('feynmanDialog').close();save();showToast('已保存你的费曼复述')});
  document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>byId(b.dataset.close).close());document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-navigate]').forEach(b=>b.onclick=()=>setView(b.dataset.navigate));
  byId('addWordButton').onclick=openAdd;byId('importButton').onclick=()=>byId('importDialog').showModal();byId('ankiButton').onclick=ankiExport;byId('reminderButton').onclick=reminderOpen;byId('profileSettings').onclick=reminderOpen;byId('heroStart').onclick=()=>beginSession(dueWords().length?'due':'new');byId('heroQuiz').onclick=()=>{setView('quiz');startQuiz()};byId('startReviewButton').onclick=()=>beginSession(dueWords().length?'due':'new');byId('progressStudyButton').onclick=()=>{setView('home')};byId('flashcard').onclick=()=>{if(!session){beginSession(dueWords().length?'due':'new');return}revealCard()};byId('flashcard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(!session)beginSession(dueWords().length?'due':'new');else revealCard()}};byId('againButton').onclick=()=>scoreReview(false);byId('knownButton').onclick=()=>scoreReview(true);byId('speakWord').onclick=()=>speak(byId('wordInput').value);byId('searchWords').oninput=renderVocab;byId('filterWords').onchange=renderVocab;byId('sortWords').onchange=renderVocab;byId('languageSelect').onchange = event => {
    try { save(); } catch { event.target.value=state.language; return showToast('存储空间不足，切换前请备份数据'); }
    skills.stop();
    session = null; quiz = null; feynmanTarget = null;
    workspace.active = event.target.value;
    workspace.profiles[workspace.active] ||= createProfile(workspace.active);
    state = workspace.profiles[workspace.active];
    byId('searchWords').value = '';
    save(); render(); renderQuizIntro(); setView('home'); skills.refresh();
    showToast('已切换到 ' + state.language + ' 的词库与学习材料');
  };document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('dialog[open]').forEach(d=>d.close())});
  const skills = installSkills({getState:()=>state,save,render,showToast,openAdd,addMinutes});
  byId('heroStart').onclick = () => document.querySelector('.skill-workspace').scrollIntoView({behavior:'smooth'});
  if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});render();checkReminder();setInterval(checkReminder,30000);
})();
